"たんご": "語言的最小單位，單詞。/五月五日的節日。/源自阿根廷的舞蹈與音樂，探戈。/京都北部的舊國名「丹後」。",
"げんご": "人用來傳達意思的聲音與文字體系，語言。",
"ごんご": "用於「言語道断」，指荒唐得說不出話。",
"こんご": "從今往後。此後。/非洲中部的國名，剛果。",
"かんご": "照顧病人，看護。/用漢字音讀的詞。/監督並保護。",
