"せんご": "戰爭結束之後。特指第二次世界大戰後。",
"ぜんご": "前面和後面。/大約那個程度。「三十歳前後」（三十歲左右）。",
"ぶんご": "書面語。特指古典文體。/大分縣的舊國名「豊後」。",
"ぼんご": "拉丁音樂使用的小鼓，邦哥鼓。/梵語。",
"ろんご": "記載孔子及其弟子言行的書，《論語》。",
"れんご": "兩個以上的詞結合起來表示一個意思。",
"じんご": "他人之後。「人後に落ちない」（不落人後）。",
"ちんご": "平定動亂、守護國家。「鎮護国家」。",
"あんご": "僧人閉關一定期間修行。",
"びんご": "把數字排開來對號的遊戲，賓果。/說中時喊的「正是如此」。",
"けんご": "構造或防守堅固牢靠。「堅固な守り」（堅固的防守）。",
"なんご": "嬰兒發出的沒有意義的聲音，如「啊——嗚——」。",
"てんご": "關西話，指惡作劇、胡鬧。「てんごをする」。",
"ばんご": "圍棋中約定局數進行的對局。「十番碁」（十番棋）。",
"いんご": "只在同夥之間通行的話，隱語。",
"しんご": "新產生的詞語，新詞。",
"はんご": "用疑問形式強烈表達相反意思的說法。",
