"いらいら": "Bứt rứt vì mọi thứ không như ý.",
"ぷらぷら": "Vật nhẹ lủng lẳng đung đưa. / Lêu lổng không mục đích.",
"うらうら": "Nắng dịu dàng chan hoà, ngày yên ả.",
"おらおら": "Tiếng quát thô lỗ lặp lại để doạ nạt hay lấy khí thế. Đã quen thuộc trong manga và trên mạng.",
"つらつら": "Ngắm nghía hay ngẫm nghĩ kỹ càng; thấu đáo.",
"てらてら": "Bề mặt bóng nhẫy vì dầu hay ánh sáng.",
"こらこら": "'Này này' — nhắc nhở hay mắng ai đó.",
"ずらずら": "Những thứ giống nhau xếp nối dài.",
"ぬらぬら": "Bề mặt nhớt trơn.",
"どらどら": "'Nào để xem' — giục ai đó hoặc ghé nhìn.",
"そらそら": "'Kìa kìa' — tiếng hô gây chú ý hay giục giã.",
"あらあら": "'Ối trời' — ngạc nhiên, ngán ngẩm hay bối rối.",
"しらしら": "Trời hửng trắng lúc rạng đông.",
"ぴらぴら": "Vật mỏng nhẹ phất phơ.",
"やらやら": "Thán từ cổ biểu thị kinh ngạc hay than thở.",
"とらとら": "Tora-ken, trò chơi trong phòng tiệc ở khu ăn chơi, phân thắng bại bằng điệu bộ hổ, bà lão hay võ sĩ Watōnai.",
"ぼらぼら": "Hết cái này đến cái khác, liên tiếp.",
"えらえら": "Cười tươi vui vẻ, tủm tỉm.",
"のらのら": "Cử động chậm chạp. / Sống lơ mơ chẳng làm gì.",
"でらでら": "Bề mặt bóng loáng vì dầu hay băng; như teratera.",
