"よちよち": "Trẻ nhỏ chập chững bước đi loạng choạng.",
"みちみち": "Trên đường đi đến nơi nào đó; dọc đường.",
"けちけち": "Keo kiệt, tiếc từng chút tiền bạc hay công sức.",
"ばちばち": "Tiếng và cảnh tia lửa nổ lép bép dữ dội. / Hai đối thủ đối đầu gay gắt. Trong tiếng lóng giới trẻ còn dùng để nhấn mạnh 'cực kỳ, hoàn hảo'.",
