"はちはち": "Hai chữ tám. / Một trò chơi tên là hachi-hachi.",
"とちとち": "Từng vùng đất, từng địa phương.",
"うろうろ": "Đi tới đi lui không mục đích.",
"ころころ": "Vật nhỏ tròn lăn đi. / Thay đổi xoành xoạch. / Korokoro cũng là tên gọi tắt nổi tiếng của tạp chí truyện tranh Gekkan CoroCoro Comic.",
