"げろげろ": "Tiếng ếch kêu. / Khẩu ngữ diễn tả sự ghê tởm hay buồn nôn.",
"はろはろ": "Halo-halo, món tráng miệng Philippines gồm đá bào trộn trái cây, đậu và kem. Ở Nhật còn được biết đến như tên một sản phẩm của Ministop.",
