"ぐんぐん": "쑥쑥 자라거나 힘차게 나아가는 모양.",
"けんけん": "한 발로 뛰는 모양. 그 놀이의 이름.",
"こんこん": "가볍게 연달아 두드리는 소리. / 콜록거리는 기침 소리.",
"ごんごん": "종이나 단단한 것을 잇달아 치는 둔한 소리.",
