"しんしん": "눈이 소리 없이 내리는 모양. / 추위가 깊어지는 모양.",
"じんじん": "저리거나 아픔이 욱신욱신 이어지는 모양.",
"すんすん": "코를 짧게 훌쩍이며 냄새를 맡거나 우는 모양.",
"ずんずん": "망설임 없이 척척 나아가는 모양.",
"せんせん": "두려워 벌벌 떠는 모양. 「전전긍긍」의 전전.",
"ぜんぜん": "전혀(부정과 함께). 구어에서는 강한 긍정으로도 쓴다.",
"たんたん": "감정을 드러내지 않고 담담한 모양.",
"だんだん": "조금씩. / 계단처럼 층진 모양.",
"ちんちん": "몹시 뜨거운 모양(구어, 지역차 있음). / 작은 쇳소리.",
"つんつん": "끝이 뾰족하게 선 모양. / 쌀쌀맞게 구는 모양.",
"てんてん": "이곳저곳 옮겨 다니는 모양. / 점이 흩어진 모양.",
"でんでん": "「でんでん虫」(달팽이) 등에 남은 유아어 형태.",
"とんとん": "가볍게 두드리는 소리. / 일이 술술 풀리는 모양.",
