"なんこう": "일이 잘 진척되지 않는 것, 난항. / 바르는 약, 연고.",
"あんこう": "입이 큰 심해성 물고기, 아귀. 전골로 먹는다.",
"おんこう": "온화하고 남을 배려하는 것.",
"がんこう": "눈빛. 「眼光紙背に徹する」(글의 속뜻까지 꿰뚫어 본다).",
"きんこう": "균형이 잡혀 있는 것. / 도시 주변, 근교.",
