"ざんこう": "해가 진 뒤에 남는 빛.",
"たんこう": "석탄을 캐는 광산, 탄광. / 단독으로 하는 것. 「単行本」(단행본).",
"だんこう": "과감하게 실행하는 것, 단행. / 노동조합의 단체 교섭.",
