"ひんこう": "평소의 행실, 품행. 「品行方正」(품행이 방정함).",
"ぶんこう": "빛을 파장별로 나누는 것, 분광. / 본교에서 갈라져 나온 학교, 분교.",
"ほんこう": "중심이 되는 학교, 본교. 「이 학교」라는 뜻으로도 쓴다.",
"れんこう": "경찰 등이 강제로 데려가는 것, 연행.",
"ろんこう": "공적을 평가하는 것. 「論功行賞」(논공행상).",
"ばんこう": "야만적인 행위, 만행.",
"いんこう": "목구멍, 인후. 「耳鼻咽喉科」(이비인후과).",
"うんこう": "열차 등이 정해진 길을 다니는 것, 운행. / 배나 항공기의 운항.",
"ぜんこう": "착한 행실, 선행. / 학교 전체. 「全校集会」(전교 집회).",
"ちんこう": "가라앉아 내려가는 것, 침강. 「沈降作用」(침강 작용).",
"えんこう": "부처 뒤의 둥근 빛, 원광. / 원숭이. 「猿猴が月を取る」(원숭이가 물속 달을 잡으려 한다).",
"りんこう": "항구에 접해 있는 것, 임항. 「臨港線」(임항선).",
"まんこう": "온몸에 가득 차는 것. 「満腔の敬意」(만강의 경의).",
"らんこう": "여러 사람이 뒤섞여 성관계를 맺는 것, 난교.",
"くんこう": "나라나 주군을 위해 세운 공적, 훈공. 「勲功をたてる」(훈공을 세우다).",
"にんこう": "에도 후기의 천황. 「仁孝天皇」(닌코 천황).",
