"ぴんち": "궁지에 몰린 괴로운 상황.",
"ぺんち": "철사를 집거나 자르는 공구, 펜치.",
"べんち": "등받이가 있는 긴 의자. / 경기의 대기석.",
"みんち": "잘게 간 고기, 다진 고기.",
"めんち": "다진 고기. 「メンチカツ」(멘치카쓰).",
"いんち": "길이 단위 인치. 약 2.54센티미터.",
"あんち": "반대하는 입장이나 사람, 안티. 「アンチ〜」의 형태로 쓴다.",
