"ぽんち": "과일이 든 음료 「フルーツポンチ」(프루츠 펀치)의 폰치. / 약화를 뜻하는 「ポンチ絵」의 폰치.",
"さんち": "그 물건이 만들어진 땅, 산지.",
"ばんち": "토지에 붙인 번호, 번지. 주소.",
"だんち": "주택이나 공장을 한데 모아 지은 구역, 단지.",
"ぼんち": "둘레가 산으로 둘러싸인 평지, 분지.",
"かんち": "느껴 알아채는 것, 감지. / 병이 완전히 낫는 것, 완치.",
"けんち": "사물을 보는 입장, 견지. / 논밭을 측량해 조사하는 일.",
