"じんち": "군대가 자리 잡은 곳, 진지.",
"せんち": "전쟁이 벌어지고 있는 땅, 전지. / 길이 단위 센티미터. 「センチな気分」(감상적인 기분)처럼 쓰기도 한다.",
"たんち": "숨어 있는 것을 찾아내는 것, 탐지. 「魚群探知機」(어군 탐지기).",
"てんち": "하늘과 땅. 세상. / 위와 아래.",
"とんち": "그 자리에서 발휘되는 재치. 「一休さんの頓知」(잇큐의 재치).",
"にんち": "사물을 알아보고 아는 것, 인지. 「認知症」(치매).",
"ぜんち": "다치거나 병든 것이 완전히 낫는 것. 「全治二週間」(완치까지 2주).",
