"うんち": "대변을 이르는 유아어, 응가.",
"でんち": "화학 반응 등으로 전기를 꺼내는 장치, 전지.",
"らんち": "점심 식사. / 소형 배.",
"れんち": "볼트를 돌리는 공구, 렌치. 스패너.",
