"こんち": "「こんにちは」를 줄인 편한 인사. 「こんちは」.",
"えんち": "정원이나 공원으로 쓰는 땅. 「遊園地」(유원지).",
"へんち": "도시에서 먼 땅. 외진 곳.",
"もんち": "가문, 문벌. 「門地による差別」(문벌에 따른 차별).",
"なんち": "잘 낫지 않는 것, 난치. 「難治性」(난치성).",
"ごんち": "불교에서, 부처가 상대에 맞춰 방편으로 쓰는 지혜.",
"ぞんち": "알고 있는 것. 익히 알고 있음.",
"ぶんち": "무력이 아니라 학문과 법으로 세상을 다스리는 것. 「文治政治」(문치 정치).",
"ろんち": "상품이나 서비스를 세상에 내놓는 것. 「ローンチ」라고도 한다.",
