"えんじ": "유치원·어린이집에 다니는 아이. / 검은빛이 도는 붉은색.",
"かんじ": "중국에서 온 문자. / 모임 등을 맡아 챙기는 사람. / 인상·느낌.",
"きんじ": "매우 가까움. 「近似値」(근삿값).",
"ぐんじ": "군대나 전쟁에 관한 일.",
"けんじ": "형사 사건의 공소를 맡는 검사. / 「宮沢賢治」처럼 사람 이름으로도 쓴다.",
