"こんじ": "병을 뿌리부터 고치는 것. 「こんち」라고도 읽는다.",
"さんじ": "참혹한 사건. / 오후 3시.",
"ざんじ": "잠시 동안.",
"しんじ": "신을 모시는 의식.",
"じんじ": "사람의 배치나 처우에 관한 일. 인사.",
"せんじ": "전쟁을 하고 있는 시기. / 약초 등을 달여 우려내는 것.",
"ぜんじ": "덕이 높은 승려에게 주는 칭호. / 점차.",
