"てんじ": "늘어놓아 보여주는 것. / 손가락으로 읽는 점자.",
"でんじ": "전기와 자기에 관한 것. 「電磁波」(전자파).",
"なんじ": "너(옛 말투). / 어려운 일.",
"はんじ": "재판관의 관직 이름. 판사.",
"ばんじ": "모든 일. 「万事休す」(만사휴의).",
"ほんじ": "부처가 본래의 모습으로 나타난 것. 「本地垂迹」.",
"へんじ": "부름이나 물음에 대한 대답.",
"ぼんじ": "산스크리트를 적는 문자. 범자.",
"まんじ": "불교나 지도에서 절을 나타내는 기호 卍. 인터넷에서는 감탄 표현으로도 쓴다.",
"みんじ": "사인끼리의 법률관계에 관한 일. 민사.",
"もんじ": "말을 적는 기호. 문자. 「文字通り」(문자 그대로).",
"りんじ": "정해진 때가 아니라 그때만 하는 것. 임시.",
"ぞんじ": "알고 있음(겸양·정중한 말). 「ご存じ」「存じ上げる」.",
"いんじ": "문자를 종이 등에 인쇄하는 것.",
"くんじ": "윗사람이 타이르며 가르치는 말.",
"すんじ": "아주 짧은 시간. 「寸時も休まない」(잠시도 쉬지 않는다).",
"とんじ": "자기 아들을 낮추어 이르는 말.",
"そんじ": "잘못하는 것. 「書き損じ」(잘못 씀).",
"れんじ": "가는 나무나 대를 일정한 간격으로 세운 살. 「連子窓」(살창).",
"ぶんじ": "가마쿠라 초기의 연호(1185〜1190).",
"おんじ": "소리만 나타내는 글자. 표음문자.",
"ねんじ": "해마다의 것. 「年次計画」(연차 계획)「年次休暇」(연차 휴가).",
"ひんじ": "문이나 뚜껑의 경첩. / 논리학에서 판단의 술어.",
"がんじ": "기러기가 한 줄로 나는 모습을 글자에 빗댄 말. / 편지. 「雁字搦め」(꽁꽁 얽어맴).",
"いんし": "세금 등을 낼 때 쓰는 증표. 인지. / 어떤 결과를 낳는 요소. 인자.",
"おんし": "가르침을 받은, 은혜를 입은 선생님.",
"かんし": "지켜보며 감시하는 것. / 한자로 짓는 시. / 영어 등에서 명사에 붙는 관사.",
