"くんし": "덕이 높은 훌륭한 사람. 「君子危うきに近寄らず」(군자는 위험에 가까이 가지 않는다).",
"ぐんし": "작전을 세우는 참모. 군사. / 군사에 쓰는 자금.",
"けんし": "사인 등을 조사하는 것. 검시. / 명주실. / 검술에 뛰어난 사람.",
"げんし": "물질을 이루는 미립자. 원자. / 사물의 처음. 원시.",
