"ざんし": "뒤에 남은 찌꺼기. 「旧習の残滓」(구습의 잔재).",
"しんし": "예의 바른 남성. 신사. / 진지하고 한결같음.",
"すんし": "마음뿐인 작은 선물. 사례를 건넬 때 쓰는 말.",
"せんし": "싸우는 병사. 전사. / 전장에서 목숨을 잃는 것.",
"ぜんし": "어떤 시대 이전의 역사. / 신문이나 종이의 전체.",
"そんし": "중국 고대의 병법가 손자. 그 병법서.",
"たんし": "전기 기기에서 배선을 잇는 접속 부분. 단자.",
"だんし": "남자. 사내아이.",
"てんし": "신의 사자. 천사. / 천황·황제.",
"でんし": "원자를 이루는, 음전기를 띤 입자. 전자.",
"とんし": "갑자기 죽는 것. / 쇼기(장기)에서 부주의로 외통에 몰리는 것.",
"はんし": "서예에 쓰는 일본 종이. / 번(藩)을 섬긴 무사.",
