"ろんし": "논의의 취지. 「論旨明快」(논지 명쾌).",
"あんし": "어두운 곳에서 보는 것. 「暗視スコープ」(암시 스코프).",
"りんし": "죽음에 다다름. 「臨死体験」(임사 체험).",
"れんし": "검도 등의 칭호 가운데 하나.",
"えんし": "가까운 것이 잘 보이지 않는 눈. 원시.",
"ねんし": "한 해의 시작. 「年始回り」(새해 인사 다니기).",
"じんし": "사회적 지위나 식견이 있는 사람. 「有識人士」(유식 인사).",
"うんし": "악기를 연주할 때의 손가락 운용. 운지. 「運指表」(운지표).",
